# 2026-11-16 SEO/GEO yenilemesi: en çok gösterim/tıklama alan 10 yazı (blog/posts_refresh3.py).
# Düz alanlar doğrudan güncellenir ("body" verilirse gövde tamamen değişir, yukarıdaki EXTRA ekleri de düşer);
# "insert" = [(orijinal gövdedeki konum, [bölümler])] büyükten küçüğe eklenir; "faq_add" SSS sonuna eklenir.
from posts_refresh3 import REFRESH_TR3
for _r in REFRESH_TR3:
    _r = dict(_r); _p = BY_SLUG[_r["slug"]]
    _ins = _r.pop("insert", []); _fa = _r.pop("faq_add", [])
    _p.update(_r)
    _body = list(_p["body"])
    for _at, _secs in sorted(_ins, key=lambda x: -x[0]):
        if not any(h == _secs[0][0] for h, _ in _body):
            _body = _body[:_at] + list(_secs) + _body[_at:]
    _p["body"] = _body
    _p["faq"] = list(_p["faq"]) + [f for f in _fa if f[0] not in {q for q, _ in _p["faq"]}]
def strip_tags(s): return re.sub(r"<[^>]+>","",s)
def iso(d): return d  # already YYYY-MM-DD
def tr_date(d):
    months=["Ocak","Şubat","Mart","Nisan","Mayıs","Haziran","Temmuz","Ağustos","Eylül","Ekim","Kasım","Aralık"]
    y,m,dd=d.split("-"); return "%d %s %s"%(int(dd),months[int(m)-1],y)

